  "promos": [
    {
      "title": "Public Humiliation Before the Explosion",
      "start_block": "B007",
      "end_block": "B047",
      "hook": "Catherine's cruel face fills the screen as she sneers, 'I want everyone to see what happens to a woman who dares defy this family.'",
      "cliffhanger": "An ear-splitting detonation shatters the cathedral entrance as a fireball blasts the doors into shrapnel, cutting on terrified screams.",
      "why": "Starts on a villain's sadistic threat, builds through Juliana's defiant humiliation, then cuts on the explosion before Alexander's rescue is revealed.",
      "context_gap": "A stranger won't know Alexander is the one attacking, which makes the cliffhanger even more intriguing."
    },
    {
      "title": "Chained Bride's Defiant Stand",
      "start_block": "B013",
      "end_block": "B034",
      "hook": "Juliana is marched into the cathedral in chains and a prison dress as Catherine gloats, 'There she is.'",
      "cliffhanger": "Juliana's bruised face fills the screen as she fires back, 'You needed an entire chapel to feel powerful over one chained woman?'",
      "why": "Clear victim-villain dynamic in seconds, and Juliana's defiant line lands as a powerful unresolved beat before Catherine's response.",
      "context_gap": "None—the humiliation and defiance are self-explanatory."
    },
    {
      "title": "Wedding Vows Interrupted by Attack",
      "start_block": "B041",
      "end_block": "B052",
      "hook": "Catherine gazes adoringly at Rupert and whispers, 'Soon, there will be nothing left between us and the Ashburgh title.'",
      "cliffhanger": "Silhouetted armed figures emerge through the smoke and rubble as Juliana turns her head toward the light, her expression shifting to awe.",
      "why": "The conspirators' triumph is instantly shattered by the explosion, and the cut lands on Juliana's realization before Alexander is identified.",
      "context_gap": "A stranger won't know who the armed figures are, which creates a strong pull to find out."
    }
  ],
  "moments": [
    {
      "start_block": "B007",
      "end_block": "B010",
      "kind": "hook",
      "description": "Catherine halts her own wedding to publicly threaten Juliana, then commands, 'Bring her in.'"
    },
    {
      "start_block": "B013",
      "end_block": "B015",
      "kind": "emotional",
      "description": "Juliana is marched in chains, her bruised face and fierce blue eyes showing unbroken dignity."
    },
    {
      "start_block": "B034",
      "end_block": "B036",
      "kind": "hook",
      "description": "Juliana's defiant challenge to Catherine: 'You needed an entire chapel to feel powerful over one chained woman?'"
    },
    {
      "start_block": "B047",
      "end_block": "B052",
      "kind": "cliffhanger",
      "description": "The cathedral doors explode in a fireball, and armed silhouettes emerge through the smoke as Juliana turns in awe."
    }
  ]
